	public LkOrderItemViewModel CalacBeforeOperation(LkOrderItemViewModel vm)
	{
		try
		{
			int.TryParse(SysSeting.Get().DefaultLanguageID.ToString(), out var result);
			if (result <= 0)
			{
				result = 1065;
			}
			int lCID = Thread.CurrentThread.CurrentCulture.LCID;
			bool result2 = false;
			bool result3 = false;
			bool result4 = false;
			WSspSelectProductsWithId_Result wSspSelectProductsWithId_Result = Enumerable.FirstOrDefault<WSspSelectProductsWithId_Result>((IEnumerable<WSspSelectProductsWithId_Result>)_db.WSspSelectProductsWithId(vm.ordIPrdId, lCID, result));
			if (wSspSelectProductsWithId_Result != null)
			{
				bool.TryParse(wSspSelectProductsWithId_Result.PrdQtyNoFCR.ToString(), out result2);
				bool.TryParse(wSspSelectProductsWithId_Result.PrdMustFullTracingCode.ToString(), out result3);
				bool.TryParse(wSspSelectProductsWithId_Result.PrdSingleItem.ToString(), out result4);
			}
			double result5 = 1.0;
			double result6 = 1.0;
			if (vm.ordIFCR.HasValue && vm.ordIFCR != 0f)
			{
				double.TryParse(vm.ordIFCR.ToString(), out result5);
			}
			if (vm.ordIFCRI.HasValue && vm.ordIFCRI != 0f)
			{
				double.TryParse(vm.ordIFCRI.ToString(), out result6);
			}
			if (result2)
			{
				result5 = 1.0;
				result6 = 1.0;
			}
			double result7 = 0.0;
			double.TryParse(vm.ordIQuantityTotal.ToString(), out result7);
			decimal.TryParse(vm.ordIDiscount.ToString(), out var result8);
			decimal.TryParse(vm.ordIPrice.ToString(), out var result9);
			decimal.TryParse(vm.ordIRound.ToString(), out var result10);
			decimal.TryParse(vm.ordIRoundPlus.ToString(), out var result11);
			decimal.TryParse(vm.ordITax.ToString(), out var result12);
			decimal num = (decimal)((double?)vm.ordIQuantity * result5 * result6).Value;
			if (result7 > 0.0)
			{
				num = (decimal)(result7 * result6);
			}
			if (vm.ordIDiscountSum.HasValue && result8 == 0m)
			{
				result8 = vm.ordIDiscountSum.GetValueOrDefault() / num;
				vm.ordIDiscount = result8;
			}
			if (!vm.ordIDiscountSum.HasValue)
			{
				decimal? ordIDiscountSum = vm.ordIDiscountSum;
				if ((ordIDiscountSum.GetValueOrDefault() == default(decimal)) & ordIDiscountSum.HasValue)
				{
					vm.ordIDiscountSum = num * result8;
				}
			}
			_ = result9 - result8 - result10 + result11;
			decimal valueOrDefault = vm.ordIDiscountSum.GetValueOrDefault();
			decimal num2 = (result9 - result10 + result11) * num - valueOrDefault;
			decimal.TryParse(vm.ordITaxIndex.ToString(), out var result13);
			if (result13 != 0m)
			{
				vm.ordITaxSum = num2 * result13 / 100m;
			}
			else
			{
				vm.ordITaxSum = num * result12;
			}
			vm.ordIPriceSum = num2;
			vm.ordITotalPrice = vm.ordIPriceSum + vm.ordITaxSum;
		}
		catch (Exception e)
		{
			ErrorSignal.FromCurrentContext().Raise(e);
		}
		return vm;
	}

